/* ---------- structuredChecks, validateJsonLd and flattenJsonLdTypes from the extension ---------- */

const REQUIRED_BY_TYPE: Record<string, string[]> = {
  Article: ['headline'],
  NewsArticle: ['headline'],
  BlogPosting: ['headline'],
  Product: ['name'],
  Organization: ['name'],
  LocalBusiness: ['name'],
  WebSite: ['name', 'url'],
  BreadcrumbList: ['itemListElement'],
  FAQPage: ['mainEntity'],
}

function collectTypes(node: unknown, types: Set<string>): void {
  if (!node || typeof node !== 'object') return
  if (Array.isArray(node)) return node.forEach((item) => collectTypes(item, types))
  const obj = node as Record<string, unknown>
  const type = obj['@type']
  if (typeof type === 'string') types.add(type)
  if (Array.isArray(type)) type.forEach((item) => typeof item === 'string' && types.add(item))
  for (const value of Object.values(obj)) if (value && typeof value === 'object') collectTypes(value, types)
}

function hasProperty(node: unknown, prop: string): boolean {
  if (!node || typeof node !== 'object') return false
  if (Array.isArray(node)) return node.some((item) => hasProperty(item, prop))
  const obj = node as Record<string, unknown>
  if (prop in obj && obj[prop] != null && obj[prop] !== '') return true
  return Object.values(obj).some((value) => value && typeof value === 'object' && hasProperty(value, prop))
}

function schemaChecks(blocks: object[]): { severity: Severity | 'notice' | 'ok'; message: string }[] {
  const types = new Set<string>()
  blocks.forEach((block) => collectTypes(block, types))
  const checks: { severity: Severity | 'notice' | 'ok'; message: string }[] = [
    blocks.length > 0
      ? { severity: 'ok', message: `${blocks.length} JSON-LD block(s).` }
      : { severity: 'notice', message: 'No JSON-LD found.' },
  ]
  if (types.size > 0) checks.push({ severity: 'ok', message: `Schema types: ${[...types].join(', ')}.` })
  for (const block of blocks) {
    const own = new Set<string>()
    collectTypes(block, own)
    for (const type of own) {
      const missing = (REQUIRED_BY_TYPE[type] ?? []).filter((prop) => !hasProperty(block, prop))
      if (missing.length) checks.push({ severity: 'warning', message: `${type} missing: ${missing.join(', ')}.` })
    }
  }
  return checks
}

